using Ufw.Shared.Firewall;
using Ufw.Shared.Firewall.SystemState;
using Ufw.Systemd.Interop.Iptables.Grammars;

namespace Ufw.Systemd.Tests.Interop.Iptables;

[TestClass]
public sealed class IptablesSaveGrammarTests
{
    [TestMethod]
    public void TryParse_PreservesChainsPoliciesOrderNegationAndOpaqueMatches()
    {
        const string save = """
            # Generated by iptables-save v1.8.10
            *nat
            :PREROUTING ACCEPT [0:0]
            :POSTROUTING ACCEPT [1:2]
            -A POSTROUTING -j MASQUERADE
            COMMIT
            *filter
            :INPUT DROP [10:20]
            :FORWARD ACCEPT [0:0]
            :OUTPUT DROP [0:0]
            :ufw-user-input - [0:0]
            :ufw-user-forward - [3:4]
            -A INPUT [5:6] -j ufw-before-input
            -A INPUT -p tcp ! -s 10.1.2.3/24 -i eth+ -o ! lo -m conntrack --ctstate NEW -m recent --set --name DEFAULT -j ufw-user-input
            -A ufw-user-input -p tcp -m multiport --dports 443,80 --sports 1000:1010 -g ufw-user-forward
            -A ufw-user-input -m tcp --dport ! 22 -j REJECT --reject-with tcp-reset
            -A ufw-user-forward -s 192.168.0.1/255.255.255.0 -p udp --sport 53 -j ACCEPT
            -A OUTPUT -m comment --comment "keep me" -j ACCEPT
            COMMIT
            # Completed
            """;

        Assert.IsTrue(IptablesSaveGrammar.Instance.TryParse(save, FirewallAddressFamily.IPv4, out RawFilterTable? table));
        Assert.AreEqual(FirewallAddressFamily.IPv4, table.AddressFamily);
        Assert.HasCount(5, table.Chains);
        Assert.AreEqual(FilterChainPolicy.Drop, Chain(table, "INPUT").Policy);
        Assert.AreEqual(FilterChainPolicy.None, Chain(table, "ufw-user-input").Policy);
        Assert.HasCount(2, Chain(table, "INPUT").Rules);
        Assert.AreEqual(0, Chain(table, "INPUT").Rules[0].Location.Index);
        Assert.AreEqual(1, Chain(table, "INPUT").Rules[1].Location.Index);

        RawFilterRule routed = Chain(table, "INPUT").Rules[1];
        Assert.IsTrue(routed.Target.IsChainReference);
        Assert.AreEqual("ufw-user-input", routed.Target.Name);
        Assert.AreEqual(FilterClauseKind.Protocol, routed.Clauses[0].Kind);
        Assert.AreEqual("tcp", routed.Clauses[0].Value);
        FilterClause source = routed.Clauses.Single(static clause => clause.Kind == FilterClauseKind.SourceAddress);
        Assert.IsTrue(source.Negated);
        Assert.AreEqual("10.1.2.0/24", source.Value);
        Assert.AreEqual("eth+", routed.Clauses.Single(static clause => clause.Kind == FilterClauseKind.IngressInterface).Value);
        FilterClause egress = routed.Clauses.Single(static clause => clause.Kind == FilterClauseKind.EgressInterface);
        Assert.IsTrue(egress.Negated);
        Assert.AreEqual("lo", egress.Value);
        Assert.AreEqual("-m conntrack --ctstate NEW", routed.Clauses[4].Value);
        StringAssert.StartsWith(routed.Clauses[5].Value, "-m recent --set");

        RawFilterRule multiport = Chain(table, "ufw-user-input").Rules[0];
        Assert.AreEqual(FilterTargetKind.Goto, multiport.Target.Kind);
        Assert.IsTrue(multiport.Target.IsChainReference);
        Assert.AreEqual("80,443", multiport.Clauses.Single(static clause => clause.Kind == FilterClauseKind.DestinationPort).Value);
        Assert.AreEqual("1000:1010", multiport.Clauses.Single(static clause => clause.Kind == FilterClauseKind.SourcePort).Value);

        RawFilterRule rejected = Chain(table, "ufw-user-input").Rules[1];
        Assert.IsFalse(rejected.Target.IsChainReference);
        Assert.AreEqual("REJECT", rejected.Target.Name);
        Assert.AreEqual("--reject-with tcp-reset", rejected.Target.Arguments);
        FilterClause port = rejected.Clauses.Single(static clause => clause.Kind == FilterClauseKind.DestinationPort);
        Assert.IsTrue(port.Negated);
        Assert.AreEqual("22", port.Value);
        Assert.IsFalse(rejected.Clauses.Any(static clause => clause.Kind == FilterClauseKind.Opaque));

        RawFilterRule dns = Chain(table, "ufw-user-forward").Rules[0];
        Assert.AreEqual("192.168.0.0/24", dns.Clauses.Single(static clause => clause.Kind == FilterClauseKind.SourceAddress).Value);
        Assert.AreEqual("53", dns.Clauses.Single(static clause => clause.Kind == FilterClauseKind.SourcePort).Value);

        RawFilterRule commented = Chain(table, "OUTPUT").Rules[0];
        Assert.AreEqual("-m comment --comment \"keep me\"", commented.Clauses.Single().Value);
    }

    [TestMethod]
    public void TryParse_ReadsInstalledUfwRuleFilesWhenPresent()
    {
        ParseIfPresent("/etc/ufw/before.rules", FirewallAddressFamily.IPv4);
        ParseIfPresent("/etc/ufw/after.rules", FirewallAddressFamily.IPv4);
        ParseIfPresent("/etc/ufw/before6.rules", FirewallAddressFamily.IPv6);
        ParseIfPresent("/etc/ufw/after6.rules", FirewallAddressFamily.IPv6);
    }

    [TestMethod]
    public void TryParse_RejectsAMissingFilterTableAndDuplicateFilterTables()
    {
        const string natOnly = """
            *nat
            :PREROUTING ACCEPT [0:0]
            COMMIT
            """;
        const string duplicate = """
            *filter
            :INPUT ACCEPT [0:0]
            :FORWARD ACCEPT [0:0]
            :OUTPUT ACCEPT [0:0]
            COMMIT
            *filter
            :INPUT DROP [0:0]
            :FORWARD DROP [0:0]
            :OUTPUT DROP [0:0]
            COMMIT
            """;

        Assert.IsFalse(IptablesSaveGrammar.Instance.TryParse(natOnly, FirewallAddressFamily.IPv4, out _));
        Assert.IsFalse(IptablesSaveGrammar.Instance.TryParse(duplicate, FirewallAddressFamily.IPv4, out _));
        Assert.IsFalse(IptablesSaveGrammar.Instance.TryParse("*filter\n:INPUT ACCEPT [0:0]\n-A MISSING -j ACCEPT\nCOMMIT\n", FirewallAddressFamily.IPv4, out _));
    }

    [TestMethod]
    public void TryParse_CanonicalizesIpv6AddressesAndKeepsOpaqueExtensionHeaders()
    {
        const string save = """
            *filter
            :INPUT DROP [0:0]
            :FORWARD DROP [0:0]
            :OUTPUT ACCEPT [0:0]
            -A INPUT -p icmpv6 --icmpv6-type router-solicitation -m hl --hl-eq 255 -s fe80::1/10 -j ACCEPT
            -A INPUT -d ff02::fb -p udp --dport 5353 -j ACCEPT
            COMMIT
            """;

        Assert.IsTrue(IptablesSaveGrammar.Instance.TryParse(save, FirewallAddressFamily.IPv6, out RawFilterTable? table));
        RawFilterRule solicitation = table.Chains[0].Rules[0];
        Assert.AreEqual("icmpv6", solicitation.Clauses[0].Value);
        Assert.AreEqual("--icmpv6-type router-solicitation", solicitation.Clauses[1].Value);
        Assert.AreEqual("-m hl --hl-eq 255", solicitation.Clauses[2].Value);
        Assert.AreEqual("fe80::/10", solicitation.Clauses.Single(static clause => clause.Kind == FilterClauseKind.SourceAddress).Value);
        Assert.AreEqual("ff02::fb", table.Chains[0].Rules[1].Clauses.Single(static clause => clause.Kind == FilterClauseKind.DestinationAddress).Value);
    }

    private static void ParseIfPresent(string path, FirewallAddressFamily family)
    {
        if (!File.Exists(path))
        {
            return;
        }

        string text = File.ReadAllText(path);
        Assert.IsTrue(IptablesSaveGrammar.Instance.TryParse(text, family, out RawFilterTable? table), path);
        Assert.IsTrue(table.Chains.Count > 0, path);
    }

    private static RawFilterChain Chain(RawFilterTable table, string name) => table.Chains.Single(chain => chain.Name == name);
}
